SELECT id,CAST(json_extract(properties,'$.thread_id') AS TEXT) FROM notes WHERE namespace=?1 AND kind='message' AND deleted_at IS NULL AND ((json_extract(properties,'$.from_actor')=?2 AND json_extract(properties,'$.to_actor')=?3) OR (json_extract(properties,'$.from_actor')=?3 AND json_extract(properties,'$.to_actor')=?2)) AND (json_extract(properties,'$.external_id')=?4 OR json_extract(properties,'$.thread_id') IN (?5,?6,?7,?8,?9,?10,?11,?12,?13) OR id=?14) ORDER BY created_at,id LIMIT 1
